    K << 200, -100,   0,   0,
        -100,  200, -100,   0,
           0, -100,  200, -100,
           0,    0, -100,  100;

    Eigen::VectorXd xexact(n);
    xexact << 1, 2, 3, 4;
    Eigen::VectorXd b = K * xexact;

    // Solve
    Eigen::MatrixXd A = K;
    Eigen::MatrixXd B(n, 1);
    B.col(0) = b;
    double determ = 0.0;
    int ising = 1;
    Eigen::MatrixXi INDEX(n, 3);
    INDEX.setZero();

    INVERD(n, A, n, B, 1, determ, ising, INDEX);

    Eigen::VectorXd x = B.col(0);
    Eigen::MatrixXd Kinv = A;

    std::cout << std::setprecision(15);
    std::cout << "{\"test\":\"INVERD\",\"solution\":[";
    for (int i = 0; i < n; ++i) {
        if (i) std::cout << ",";
        std::cout << x(i);
    }
    std::cout << "],\"determinant\":" << determ << ",\"inverse\":[";
    for (int i = 0; i < n; ++i) {
        std::cout << "[";
        for (int j = 0; j < n; ++j) {
            if (j) std::cout << ",";
            std::cout << Kinv(i, j);
        }
        std::cout << "]";
        if (i + 1 < n) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
