                } else {
                    ising = 2;
                    return;
                }
            }
        }
        INDEX(icolum, 2) = INDEX(icolum, 2) + 1;
        INDEX(i, 0) = irow;
        INDEX(i, 1) = icolum;

        if (irow != icolum) {
            determ = -determ;
            for (int l = 0; l < n; ++l) {
                double swap = A(irow, l);
                A(irow, l) = A(icolum, l);
                A(icolum, l) = swap;
            }
            if (m > 0) {
                for (int l = 0; l < m; ++l) {
                    double swap = B(irow, l);
                    B(irow, l) = B(icolum, l);
                    B(icolum, l) = swap;
                }
            }
        }

        double pivot = A(icolum, icolum);
        determ = determ * pivot;

        if (std::fabs(pivot) < epsi) {
            ising = 2;
            return;
        }
        A(icolum, icolum) = 1.0;
        for (int l = 0; l < n; ++l)
            A(icolum, l) = A(icolum, l) / pivot;
        if (m > 0) {
            for (int l = 0; l < m; ++l)
                B(icolum, l) = B(icolum, l) / pivot;
        }

        for (int l1 = 0; l1 < n; ++l1) {
            if (l1 == icolum) continue;
            double t = A(l1, icolum);
            A(l1, icolum) = 0.0;
