            for (int l = 0; l < n; ++l)
                A(l1, l) = A(l1, l) - A(icolum, l) * t;
            if (m > 0) {
                for (int l = 0; l < m; ++l)
                    B(l1, l) = B(l1, l) - B(icolum, l) * t;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        int l = n - 1 - i;
        if (INDEX(l, 0) == INDEX(l, 1)) continue;
        int jrow = INDEX(l, 0);
        int jcolum = INDEX(l, 1);
        for (int k = 0; k < n; ++k) {
            double swap = A(k, jrow);
            A(k, jrow) = A(k, jcolum);
            A(k, jcolum) = swap;
        }
    }

    for (int k = 0; k < n; ++k) {
        if (INDEX(k, 2) == 1) continue;
        ising = 2;
        return;
